// FUENTE: dirección donde el sistema académico del colegio deja sus 6 exportes en CSV.
// En la demostración, la Mac la sirve desde data/bronze/dataset-ficticio-colegio (scripts/encender_produccion.sh).
const FUENTE = 'http://host.docker.internal:8790';
// Columnas del contrato de E-Pakty (backend/production/validation.py). Lo demás se descarta.
const TABLAS = {
  estudiantes: 'codigo nombre_ficticio curso paralelo anio_nacimiento genero necesidad_educativa beca_porcentaje representante_codigo fecha_ingreso',
  docentes: 'codigo nombre_ficticio materia_principal',
  asistencia: 'codigo_estudiante fecha estado',
  notas: 'codigo_estudiante anio_lectivo quimestre parcial materia nota',
  pensiones: 'codigo_estudiante mes valor estado fecha_pago',
  horarios: 'curso paralelo dia hora_inicio hora_fin materia docente_codigo'
};
return Object.entries(TABLAS).map(([tabla, columnas]) => ({ json: { tabla, columnas: columnas.split(' '), url: `${FUENTE}/${tabla}.csv` } }));

const crypto = require('crypto');
const conf = $('Dónde están los archivos del colegio').all();
const csvs = $input.all();
// Lector de CSV con comillas ("a, b" y "" dentro de un campo).
function leer(texto) {
  const filas = []; let fila = [], campo = '', comillas = false;
  texto = String(texto || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (comillas) {
      if (c === '"' && texto[i + 1] === '"') { campo += '"'; i++; }
      else if (c === '"') comillas = false;
      else campo += c;
    } else if (c === '"') comillas = true;
    else if (c === ',') { fila.push(campo); campo = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && texto[i + 1] === '\n') i++;
      fila.push(campo); campo = '';
      if (fila.some(x => x !== '')) filas.push(fila);
      fila = [];
    } else campo += c;
  }
  fila.push(campo); if (fila.some(x => x !== '')) filas.push(fila);
  return filas;
}
const tablas = {};
conf.forEach((c, i) => {
  const { tabla, columnas } = c.json;
  const filas = leer(csvs[i] && csvs[i].json.csv);
  if (filas.length < 2) throw new Error(`${tabla}.csv llegó vacío o no se pudo leer`);
  const cab = filas[0].map(x => x.trim());
  const faltan = columnas.filter(x => !cab.includes(x));
  if (faltan.length) throw new Error(`${tabla}.csv: faltan columnas ${faltan.join(', ')}`);
  tablas[tabla] = filas.slice(1).map(f => Object.fromEntries(columnas.map(col => [col, (f[cab.indexOf(col)] ?? '').trim()])));
});
// La clave cambia si cambia el contenido: dos corridas con los mismos datos no duplican la carga.
const huella = crypto.createHash('sha256').update(JSON.stringify(tablas)).digest('hex').slice(0, 16);
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Guayaquil' }).replace(/-/g, '');
const filasPorTabla = Object.fromEntries(Object.entries(tablas).map(([k, v]) => [k, v.length]));
return [{ json: { clave: `nocturna-${hoy}-${huella}`, filas: filasPorTabla, cuerpo: { synthetic_declaration: true, tablas } } }];

const r = $input.first().json;
const a = $('Armar las 6 tablas').first().json;
return [{ json: { trabajo: r.job_id || r.trabajo || null, nuevo: r.nuevo ?? r.created ?? null, estado: r.status || r.estado || 'en cola', clave: a.clave, filas: a.filas } }];
